import{_ as o,o as t,c as e,ag as r}from"./chunks/framework.CAXxHpAX.js";const c=JSON.parse('{"title":"常见问题汇编","description":"","frontmatter":{},"headers":[],"relativePath":"99-运维/99-运维/FAQ-常见问题.md","filePath":"99-运维/99-运维/FAQ-常见问题.md","lastUpdated":null}'),q={name:"99-运维/99-运维/FAQ-常见问题.md"};function l(h,a,u,n,p,i){return t(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="常见问题汇编" tabindex="-1">常见问题汇编 <a class="header-anchor" href="#常见问题汇编" aria-label="Permalink to &quot;常见问题汇编&quot;">​</a></h1><blockquote><p>从数千条答疑中提炼的最常见问题。按主题分类，每条回答有原文出处。</p></blockquote><hr><h2 id="一、静坐与练功" tabindex="-1">一、静坐与练功 <a class="header-anchor" href="#一、静坐与练功" aria-label="Permalink to &quot;一、静坐与练功&quot;">​</a></h2><h3 id="q1-静坐时杂念太多怎么办" tabindex="-1">Q1：静坐时杂念太多怎么办？ <a class="header-anchor" href="#q1-静坐时杂念太多怎么办" aria-label="Permalink to &quot;Q1：静坐时杂念太多怎么办？&quot;">​</a></h3><blockquote><p><strong>&quot;有杂念是正常的。不怕念起，只怕觉迟。走神了——让走神，知道走神就不走神。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/答疑2021-不怕念起只怕觉迟">答疑2021-不怕念起只怕觉迟</a></p><h3 id="q2-静坐时身体发热-发麻-有电流感-正常吗" tabindex="-1">Q2：静坐时身体发热/发麻/有电流感，正常吗？ <a class="header-anchor" href="#q2-静坐时身体发热-发麻-有电流感-正常吗" aria-label="Permalink to &quot;Q2：静坐时身体发热/发麻/有电流感，正常吗？&quot;">​</a></h3><p>正常。属于初禅八触（冷、热、动、痒、轻、重、涩、滑）。&quot;不追求，不害怕。知道就好。&quot;</p><p>— <a href="/60-原文段落/五篇灵文-温养章全段">五篇灵文-温养章全段</a></p><h3 id="q3-静坐必须双盘吗-单盘、坐椅子可以吗" tabindex="-1">Q3：静坐必须双盘吗？单盘、坐椅子可以吗？ <a class="header-anchor" href="#q3-静坐必须双盘吗-单盘、坐椅子可以吗" aria-label="Permalink to &quot;Q3：静坐必须双盘吗？单盘、坐椅子可以吗？&quot;">​</a></h3><blockquote><p><strong>&quot;椅子都可以。姿势中正安舒，不要硬撑。双盘、单盘、散盘、坐椅子都可以。&quot;</strong></p></blockquote><p>— 答疑专辑</p><h3 id="q4-静坐时想睡觉怎么办" tabindex="-1">Q4：静坐时想睡觉怎么办？ <a class="header-anchor" href="#q4-静坐时想睡觉怎么办" aria-label="Permalink to &quot;Q4：静坐时想睡觉怎么办？&quot;">​</a></h3><p>可以先睡再坐。或者睁眼微闭。如果实在困，&quot;睡醒了再坐，不勉强。&quot;</p><h3 id="q5-需要收功吗-怎么收" tabindex="-1">Q5：需要收功吗？怎么收？ <a class="header-anchor" href="#q5-需要收功吗-怎么收" aria-label="Permalink to &quot;Q5：需要收功吗？怎么收？&quot;">​</a></h3><blockquote><p><strong>&quot;加个意念说&#39;我要收功了，我要收功了&#39;，心里反复这么想。等到精神比较清醒了，然后全身关节活动活动，弯弯腰、伸伸腿、转转头、甩甩手腕。让它适应从静态到动态。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/修行即生活-收功">修行即生活-收功</a></p><p>但功夫高深后收不收功都可以。内气是自动流转的，像血液循环一样。</p><h3 id="q6-守哪里最好-下丹田还是中丹田" tabindex="-1">Q6：守哪里最好？下丹田还是中丹田？ <a class="header-anchor" href="#q6-守哪里最好-下丹田还是中丹田" aria-label="Permalink to &quot;Q6：守哪里最好？下丹田还是中丹田？&quot;">​</a></h3><p>了空居士推荐<strong>轻轻返观中丹田（膻中一带覆盖整个体腔）</strong>。或轻轻意守手指脚趾。</p><blockquote><p><strong>&quot;意守手指脚趾就等于意守全身。很容易下手。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/修行即生活-意守手指脚趾">修行即生活-意守手指脚趾</a></p><h3 id="q7-练了几天没感觉-是不是方法不对" tabindex="-1">Q7：练了几天没感觉，是不是方法不对？ <a class="header-anchor" href="#q7-练了几天没感觉-是不是方法不对" aria-label="Permalink to &quot;Q7：练了几天没感觉，是不是方法不对？&quot;">​</a></h3><blockquote><p><strong>&quot;没反应说明定境更深了。以前反应很大时属于炼精化气阶段，比较浅。现在没反应说明大小周天比较畅通了，开始进入炼气化神。&quot;</strong></p></blockquote><p>— 修心与定慧等持（20090120）</p><hr><h2 id="二、情绪与心理" tabindex="-1">二、情绪与心理 <a class="header-anchor" href="#二、情绪与心理" aria-label="Permalink to &quot;二、情绪与心理&quot;">​</a></h2><h3 id="q8-被人骂了很生气-怎么化解" tabindex="-1">Q8：被人骂了很生气，怎么化解？ <a class="header-anchor" href="#q8-被人骂了很生气-怎么化解" aria-label="Permalink to &quot;Q8：被人骂了很生气，怎么化解？&quot;">​</a></h3><blockquote><p><strong>&quot;被人骂时，试着用旁观者的心态——&#39;他为什么这么激动？&#39;而不是&#39;他在骂我！&#39;&quot;</strong></p></blockquote><p>— 答疑精选</p><blockquote><p><strong>&quot;不平静时问自己：&#39;我为什么要不平静？这样正确吗？&#39;&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/金刚经5分-保持平静的要诀">金刚经5分-保持平静的要诀</a></p><h3 id="q9-总是忍不住和别人比较-怎么办" tabindex="-1">Q9：总是忍不住和别人比较，怎么办？ <a class="header-anchor" href="#q9-总是忍不住和别人比较-怎么办" aria-label="Permalink to &quot;Q9：总是忍不住和别人比较，怎么办？&quot;">​</a></h3><blockquote><p><strong>&quot;随喜是众善奉行的第一步。看到别人做好事，心生欢喜。不要嫉妒。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/金刚经11分-随喜即众善">金刚经11分-随喜即众善</a></p><p>别人好≠我不好。万法平等在果——每个人的因缘不同。</p><h3 id="q10-过去做了错事-一直后悔自责怎么办" tabindex="-1">Q10：过去做了错事，一直后悔自责怎么办？ <a class="header-anchor" href="#q10-过去做了错事-一直后悔自责怎么办" aria-label="Permalink to &quot;Q10：过去做了错事，一直后悔自责怎么办？&quot;">​</a></h3><blockquote><p><strong>&quot;过去心不可得。过去的错已经过去了，不要在心里反复重演。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/金刚经18分-三心不可得">金刚经18分-三心不可得</a></p><p>承认、反省、放下。过去的自己已经过去了，现在开始重新来。</p><h3 id="q11-焦虑未来怎么办" tabindex="-1">Q11：焦虑未来怎么办？ <a class="header-anchor" href="#q11-焦虑未来怎么办" aria-label="Permalink to &quot;Q11：焦虑未来怎么办？&quot;">​</a></h3><blockquote><p><strong>&quot;过去心不可得，现在心不可得，未来心不可得。未来还没有来，你在焦虑一个不存在的东西。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/金刚经18分-三心不可得">金刚经18分-三心不可得</a></p><h3 id="q12-情绪来了是压着还是发泄" tabindex="-1">Q12：情绪来了是压着还是发泄？ <a class="header-anchor" href="#q12-情绪来了是压着还是发泄" aria-label="Permalink to &quot;Q12：情绪来了是压着还是发泄？&quot;">​</a></h3><blockquote><p><strong>&quot;烦恼来了，不是压制它，也不是随它去。是——看清楚它，然后做该做的事。&quot;</strong></p></blockquote><p>— 答疑精选</p><hr><h2 id="三、人际关系" tabindex="-1">三、人际关系 <a class="header-anchor" href="#三、人际关系" aria-label="Permalink to &quot;三、人际关系&quot;">​</a></h2><h3 id="q13-和家人处不好怎么办" tabindex="-1">Q13：和家人处不好怎么办？ <a class="header-anchor" href="#q13-和家人处不好怎么办" aria-label="Permalink to &quot;Q13：和家人处不好怎么办？&quot;">​</a></h3><blockquote><p><strong>&quot;家庭里面最重要还是我们男人。如果妻子不开心，你拉拉手摇摇肩膀都可以。两个人都是硬邦邦的，永远摆不平的。石头和石头之间不填上水泥浆，那个石头永远是摆不平的。&quot;</strong></p></blockquote><p>— 修行入世（20090112b）</p><h3 id="q14-遇到不喜欢的人怎么相处" tabindex="-1">Q14：遇到不喜欢的人怎么相处？ <a class="header-anchor" href="#q14-遇到不喜欢的人怎么相处" aria-label="Permalink to &quot;Q14：遇到不喜欢的人怎么相处？&quot;">​</a></h3><blockquote><p><strong>&quot;功夫更深了你要想象和你的仇人在一起修炼，从恨他修到原谅他甚至是同情他。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/答疑2014-顺逆皆修与冤亲平等">答疑2014-顺逆皆修与冤亲平等</a></p><h3 id="q15-要不要帮助一个不太熟的人" tabindex="-1">Q15：要不要帮助一个不太熟的人？ <a class="header-anchor" href="#q15-要不要帮助一个不太熟的人" aria-label="Permalink to &quot;Q15：要不要帮助一个不太熟的人？&quot;">​</a></h3><blockquote><p><strong>&quot;了解就多帮助，不了解就少帮助，这是最客观的。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/金刚经4分-布施的分寸">金刚经4分-布施的分寸</a></p><hr><h2 id="四、修行观念" tabindex="-1">四、修行观念 <a class="header-anchor" href="#四、修行观念" aria-label="Permalink to &quot;四、修行观念&quot;">​</a></h2><h3 id="q16-什么是开悟-怎么知道自己开悟了" tabindex="-1">Q16：什么是开悟？怎么知道自己开悟了？ <a class="header-anchor" href="#q16-什么是开悟-怎么知道自己开悟了" aria-label="Permalink to &quot;Q16：什么是开悟？怎么知道自己开悟了？&quot;">​</a></h3><blockquote><p><strong>&quot;开悟不是毕业，开悟是入学了。悟了之后还有很长的路要走。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/金刚经5分-开悟与悟后迷">金刚经5分-开悟与悟后迷</a></p><blockquote><p><strong>&quot;实无有法名阿罗汉——不觉得自己证得了什么，才是真正的证得。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/金刚经9分-离欲与一相无相">金刚经9分-离欲与一相无相</a></p><h3 id="q17-修行一定要有师父吗" tabindex="-1">Q17：修行一定要有师父吗？ <a class="header-anchor" href="#q17-修行一定要有师父吗" aria-label="Permalink to &quot;Q17：修行一定要有师父吗？&quot;">​</a></h3><blockquote><p><strong>&quot;信的是法，不是人。老师只是一个指路人，路要自己走。我的每一句话你都可以去验证。&quot;</strong></p></blockquote><p>— 答疑专辑</p><h3 id="q18-念佛要计数量吗" tabindex="-1">Q18：念佛要计数量吗？ <a class="header-anchor" href="#q18-念佛要计数量吗" aria-label="Permalink to &quot;Q18：念佛要计数量吗？&quot;">​</a></h3><p>不用计数器。用心念——&quot;一字一句心里清清楚楚&quot;（心念耳闻）。同时显现自己在极乐，调出开心。</p><p>— <a href="/60-原文段落/念佛-显现极乐">念佛-显现极乐</a></p><h3 id="q19-多久才能有功夫" tabindex="-1">Q19：多久才能有功夫？ <a class="header-anchor" href="#q19-多久才能有功夫" aria-label="Permalink to &quot;Q19：多久才能有功夫？&quot;">​</a></h3><blockquote><p><strong>&quot;百日功灵，必有变化。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/五篇灵文-温养章全段">五篇灵文-温养章全段</a></p><p>但这是自然规律，不是硬指标。每个人的因缘不同。不要天天盯着&quot;我有没有进步&quot;。</p><h3 id="q20-修行和赚钱冲突吗" tabindex="-1">Q20：修行和赚钱冲突吗？ <a class="header-anchor" href="#q20-修行和赚钱冲突吗" aria-label="Permalink to &quot;Q20：修行和赚钱冲突吗？&quot;">​</a></h3><p>不冲突。&quot;该花一万不会花九千，不该花的五元都不愿意花&quot;——取之有道，用之不执。修行人也要吃饭。</p><p>— 答疑专辑2019处世篇</p><hr><blockquote><p>创建日期：2026-05-07 | 从答疑专辑2014/2019/2021、论坛语录、修行即生活、念佛法门问答录等提炼</p></blockquote>',80)])])}const b=o(q,[["render",l]]);export{c as __pageData,b as default};
